// Some portions generated by Claude Code
package org.eclipse.rdf4j.workbench.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.StringReader;
import java.util.List;

import org.eclipse.rdf4j.common.exception.ValidationException;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.Namespace;
import org.eclipse.rdf4j.model.impl.SimpleNamespace;
import org.eclipse.rdf4j.repository.RepositoryException;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.Rio;
import org.junit.jupiter.api.Test;

/**
 * A SHACL validation report as a person reads it (C13): one line per result with its focus node, path, value and what
 * was expected, instead of the report's RDF.
 */
class ShaclValidationSummaryTest {

	private static final String PREFIXES = """
			@prefix sh: <http://www.w3.org/ns/shacl#> .
			@prefix rdf4j: <http://rdf4j.org/schema/rdf4j#> .
			@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
			@prefix ex: <http://example.org/> .
			""";

	/** The report the RDF4J Server answered for two people without a valid age or name (as received, unsorted). */
	private static final String REPORT = PREFIXES + """
			[] a sh:ValidationReport ; sh:conforms false ; rdf4j:truncated false ;
			  sh:result [ a sh:ValidationResult ; sh:focusNode ex:bob ; sh:resultPath ex:age ;
			      sh:resultSeverity sh:Violation ; sh:sourceConstraintComponent sh:MaxCountConstraintComponent ;
			      sh:sourceShape _:age ] ,
			    [ a sh:ValidationResult ; sh:focusNode ex:alice ; sh:resultPath ex:age ; sh:value "abc" ;
			      sh:resultSeverity sh:Violation ; sh:sourceConstraintComponent sh:DatatypeConstraintComponent ;
			      sh:sourceShape _:age ] ,
			    [ a sh:ValidationResult ; sh:focusNode ex:alice ; sh:resultPath ex:name ;
			      sh:resultMessage "Every person needs a name"@en ; sh:resultSeverity sh:Violation ;
			      sh:sourceConstraintComponent sh:MinCountConstraintComponent ; sh:sourceShape _:name ] .
			_:age a sh:PropertyShape ; sh:path ex:age ; sh:datatype xsd:integer ; sh:maxCount 1 .
			_:name a sh:PropertyShape ; sh:path ex:name ; sh:minCount 1 ; sh:message "Every person needs a name"@en .
			""";

	private static final List<Namespace> REPOSITORY_NAMESPACES = List
			.of(new SimpleNamespace("ex", "http://example.org/"));

	@Test
	void eachResultIsALineWithItsFocusNodePathValueAndWhatWasExpected() throws Exception {
		String summary = ShaclValidationSummary.summarize(report(REPORT), REPOSITORY_NAMESPACES);

		assertThat(summary).isEqualTo("""
				SHACL validation failed with 3 violations:
				- ex:alice, ex:age: value "abc": expected datatype xsd:integer
				- ex:alice, ex:name: Every person needs a name
				- ex:bob, ex:age: expected at most 1 value""");
	}

	@Test
	void namesWithoutAKnownNamespaceAreWrittenInFull() throws Exception {
		Model report = report(REPORT);
		report.removeNamespace("ex");

		String summary = ShaclValidationSummary.summarize(report, List.of());

		assertThat(summary).contains(
				"- <http://example.org/alice>, <http://example.org/age>: value \"abc\": expected datatype xsd:integer");
	}

	@Test
	void warningsComplexPathsAndShapeParametersAreDescribed() throws Exception {
		String summary = ShaclValidationSummary.summarize(
				report(PREFIXES
						+ """
								[] a sh:ValidationReport ; sh:conforms false ;
								  sh:result [ a sh:ValidationResult ; sh:focusNode ex:alice ; sh:resultPath [ sh:inversePath ex:knows ] ;
								      sh:value ex:carol ; sh:resultSeverity sh:Warning ;
								      sh:sourceConstraintComponent sh:ClassConstraintComponent ; sh:sourceShape _:knows ] ,
								    [ a sh:ValidationResult ; sh:focusNode ex:bob ; sh:resultPath ( ex:address ex:city ) ;
								      sh:resultSeverity sh:Violation ;
								      sh:sourceConstraintComponent sh:MinCountConstraintComponent ; sh:sourceShape _:city ] .
								_:knows a sh:PropertyShape ; sh:class ex:Person .
								_:city a sh:PropertyShape ; sh:minCount 2 .
								"""),
				REPOSITORY_NAMESPACES);

		assertThat(summary).isEqualTo("""
				SHACL validation failed with 2 results:
				- [Warning] ex:alice, ^ex:knows: value ex:carol: expected an instance of ex:Person
				- ex:bob, ex:address/ex:city: expected at least 2 values""");
	}

	@Test
	void aLongReportListsTheFirstResultsAndSaysHowManyMoreThereAre() throws Exception {
		StringBuilder turtle = new StringBuilder(PREFIXES).append("[] a sh:ValidationReport ; sh:conforms false ; ")
				.append("rdf4j:truncated true ; sh:result ");
		for (int index = 0; index < 25; index++) {
			turtle.append(index == 0 ? "" : ", ")
					.append("[ a sh:ValidationResult ; sh:focusNode ex:item")
					.append(String.format("%02d", index))
					.append(" ; sh:resultPath ex:name ; sh:resultSeverity sh:Violation ; ")
					.append("sh:sourceConstraintComponent sh:MinCountConstraintComponent ; sh:sourceShape _:name ]");
		}
		turtle.append(" . _:name a sh:PropertyShape ; sh:minCount 1 .");

		String summary = ShaclValidationSummary.summarize(report(turtle.toString()), REPOSITORY_NAMESPACES);

		List<String> lines = summary.lines().toList();
		assertThat(lines.get(0)).isEqualTo("SHACL validation failed with 25 violations:");
		assertThat(lines).contains("- ex:item00, ex:name: expected at least 1 value",
				"- ex:item19, ex:name: expected at least 1 value", "- and 5 more")
				.noneMatch(line -> line.startsWith("- ex:item20"));
		assertThat(lines.get(lines.size() - 1))
				.isEqualTo("The server stopped validating early, so there may be more violations.");
	}

	@Test
	void theReportIsFoundAmongTheCausesOfAFailure() throws Exception {
		Model model = report(REPORT);
		RepositoryException failure = new RepositoryException(new RuntimeException(new Report(model)));

		assertThat(ShaclValidationSummary.find(failure)).hasValueSatisfying(
				report -> assertThat(report.validationReportAsModel()).isSameAs(model));
		assertThat(ShaclValidationSummary.of(failure, REPOSITORY_NAMESPACES))
				.hasValueSatisfying(summary -> assertThat(summary).startsWith("SHACL validation failed with 3"));
		assertThat(ShaclValidationSummary.find(new RepositoryException("unrelated"))).isEmpty();
	}

	private static Model report(String turtle) throws Exception {
		return Rio.parse(new StringReader(turtle), "", RDFFormat.TURTLE);
	}

	private static final class Report extends RuntimeException implements ValidationException {
		private static final long serialVersionUID = 1L;

		private final transient Model model;

		private Report(Model model) {
			this.model = model;
		}

		@Override
		public Model validationReportAsModel() {
			return model;
		}
	}
}
